function createRoadParkingBrakeConfig(maximumTorque) {
  return {
    axle: "rear",
    maximumTorque,
    applyRate: 2,
    releaseRate: 4,
    maximumStaticApplySpeed: 0.5,
    emergencyBrakeDemand: 0.65,
    emergencyResponse: 5,
    autoApplyOnIgnitionOff: true,
    autoApplyInPark: true,
    autoReleaseOnDrive: true,
    releaseThrottle: 0.16
  };
}
function createRoadAutoHoldConfig() {
  return {
    enabledByDefault: true,
    maximumCaptureSpeed: 0.06,
    captureBrake: 0.25,
    minimumHoldPressure: 0.55,
    releaseThrottle: 0.16,
    releaseThrottleHysteresis: 0.04,
    releaseDelay: 0.08,
    applyRate: 8,
    releaseRate: 4
  };
}

