function drawPrancingHorse(context, x, y, size) {
  context.save();
  context.translate(x - size * 0.5, y - size * 0.5);
  context.scale(size / 100, size / 100);
  context.fillStyle = "#121619";
  context.beginPath();
  outline.forEach(([px2, py2], i) => i ? context.lineTo(px2, py2) : context.moveTo(px2, py2));
  context.closePath();
  context.fill();
  context.restore();
}
function createPrancingHorseBadge() {
  const root = new Group();
  root.name = "Ferrari steering wheel badge";
  const disk = new Mesh(
    new CircleGeometry(0.024, 40),
    new MeshStandardMaterial({ color: 15781424, roughness: 0.4, metalness: 0.18 })
  );
  disk.name = "Ferrari yellow badge ground";
  root.add(disk);
  const shape = new Shape(outline.map(([x, y]) => new Vector2((x - 50) * 36e-5, (50 - y) * 36e-5)));
  const horse = new Mesh(
    new ShapeGeometry(shape),
    new MeshStandardMaterial({ color: 1053463, roughness: 0.36 })
  );
  horse.name = "Ferrari black prancing horse";
  horse.position.z = 7e-4;
  root.add(horse);
  const border = new Mesh(
    new TorusGeometry(0.024, 11e-4, 6, 40),
    new MeshStandardMaterial({ color: 9474967, metalness: 0.7, roughness: 0.3 })
  );
  border.position.z = 5e-4;
  root.add(border);
  return root;
}

// src/vehicle/visual/LateralAssistDisplay.ts
function lateralBoundaryColor(state, boundary, fallback) {
  if (!state?.laneValid) return fallback;
  if (state.lkaActive && state.correctingSide === (boundary === 0 ? "left" : "right")) return "#e8be66";
  if (state.lccActive) return "#53b6d5";
  if (state.lccAvailable) return "#72a68d";
  return fallback;
}

// src/vehicle/control/LaneAssistState.ts
var LANE_ASSIST_LABELS = {
  ["OFF" /* OFF */]: "OFF",
  ["WARNING_ONLY" /* WARNING_ONLY */]: "LDW",
  ["KEEP_ASSIST" /* KEEP_ASSIST */]: "LKA",
  ["CENTERING_ASSIST" /* CENTERING_ASSIST */]: "LCC"
};

// src/vehicle/visual/LaneAssistSelectionDisplay.ts
var STYLES = {
  bmw: { foreground: "#a9c5d9", background: "#102132", edge: "#39536b", font: '"Segoe UI", sans-serif' },
  audi: { foreground: "#c4ced9", background: "#111b26", edge: "#64717f", font: '"Segoe UI Light", sans-serif' },
  tesla: { foreground: "#607c8b", background: "#f4f5f2", edge: "#c7d0d3", font: '"Segoe UI", sans-serif' },
  mercedes: { foreground: "#a9b7dd", background: "#0c1322", edge: "#3a476b", font: '"Segoe UI", sans-serif' }
};
function drawLaneAssistSelection(c, state, skin, x, y, scale = 1) {
  if (!state || state.mode === "OFF" /* OFF */ && !state.notificationVisible) return;
  const style = STYLES[skin], popup = state.notificationVisible;
  c.save();
  c.translate(x, y);
  c.scale(scale, scale);
  if (popup) {
    c.fillStyle = style.background;
    c.strokeStyle = style.edge;
    c.lineWidth = 1;
    c.beginPath();
    c.roundRect(-112, -35, 224, 70, skin === "audi" ? 3 : 9);
    c.fill();
    c.stroke();
    c.fillStyle = style.foreground;
    c.font = `18px ${style.font}`;
    c.textAlign = "center";
    c.textBaseline = "middle";
    c.fillText("Lane Assist", 0, -16);
  }
  c.translate(0, popup ? 14 : 0);
  c.strokeStyle = style.foreground;
  c.fillStyle = style.foreground;
  c.lineWidth = 2;
  c.beginPath();
  c.moveTo(-52, 11);
  c.lineTo(-48, -11);
  c.moveTo(-20, 11);
  c.lineTo(-24, -11);
  c.stroke();
  if (state.mode === "KEEP_ASSIST" /* KEEP_ASSIST */ || state.mode === "CENTERING_ASSIST" /* CENTERING_ASSIST */) {
    c.beginPath();
    c.arc(-36, 0, 7, 0, Math.PI * 2);
    c.moveTo(-43, 0);
    c.lineTo(-29, 0);
    c.moveTo(-36, 0);
    c.lineTo(-36, 7);
    c.stroke();
  }
  c.font = `500 23px ${style.font}`;
  c.textAlign = "left";
  c.textBaseline = "middle";
  c.fillText(LANE_ASSIST_LABELS[state.mode], -4, 0);
  c.restore();
}

// src/vehicle/visual/BMW530Geometry.ts
function mesh(name, geometry, material) {
  const m = new Mesh(geometry, material);
  m.name = name;
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}
function grid(name, rows, columns, point, material) {
  const positions = [], indices = [];
  for (let r = 0; r <= rows; r++) for (let c = 0; c <= columns; c++) positions.push(...point(r / rows, c / columns));
  for (let r = 0; r < rows; r++) for (let c = 0; c < columns; c++) {
    const a = r * (columns + 1) + c, b = a + columns + 1;
    indices.push(a, b, a + 1, b, b + 1, a + 1);
  }
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(positions, 3));
  g.setIndex(indices);
  g.computeVertexNormals();
  return mesh(name, g, material);
}
function polygon(name, points, material) {
  const a = new Vector3(...points[0]), b = new Vector3(...points[1]), c = new Vector3(...points[2]);
  const n = b.clone().sub(a).cross(c.clone().sub(a));
  const dominant = Math.abs(n.x) > Math.abs(n.y) && Math.abs(n.x) > Math.abs(n.z) ? "x" : Math.abs(n.y) > Math.abs(n.z) ? "y" : "z";
  const outline2 = points.map((p) => new Vector2(...dominant === "x" ? [p[2], p[1]] : dominant === "y" ? [p[0], p[2]] : [p[0], p[1]]));
  const g = new BufferGeometry();
  g.setAttribute("position", new Float32BufferAttribute(points.flat(), 3));
  g.setIndex(ShapeUtils.triangulateShape(outline2, []).flat());
  g.computeVertexNormals();
  return mesh(name, g, material);
}
