    shade.addColorStop(0, "rgba(0,0,0,0)");
    shade.addColorStop(0.42, pleat);
    shade.addColorStop(0.5, "rgba(0,0,0,.30)");
    shade.addColorStop(0.58, pleat);
    shade.addColorStop(1, "rgba(0,0,0,0)");
    context.fillStyle = shade;
    context.fillRect(x - spacing * 0.5, 0, spacing, height);
    context.strokeStyle = stitch;
    context.lineWidth = 1.4;
    context.setLineDash([4, 3.2]);
    context.beginPath();
    context.moveTo(x - 3.4, 0);
    context.lineTo(x - 3.4, height);
    context.moveTo(x + 3.4, 0);
    context.lineTo(x + 3.4, height);
    context.stroke();
