  root.add(surfaceRounded("GTI lower honeycomb intake", [1.26, 0.245, 8e-3], [0, 0.422, -h - 4e-3], front, 0.06));
  root.add(surfaceRounded("GTI rear dark valance", [1.57, 0.12, 0.01], [0, 0.215, h + 2e-3], trim, 0.03));
