    lamp(label4 + " GTI front amber", signal, [0.27, 0.012, 4e-3], [sign2 * 0.65, 0.697, -h - 0.015]);
    lamp(label4 + " GTI fog", "fogFront", [0.075, 0.045, 4e-3], [sign2 * 0.75, 0.4, -h - 0.014]);
