        { x: halfWidth * (formal ? 0.86 : 0.78), y: sport ? 0.23 : 0.26, z: halfLength + 4e-3 },
        { x: halfWidth * (formal ? 0.94 : 0.88), y: sport ? 0.48 : comfort ? 0.55 : 0.51, z: halfLength - 6e-3 },
        { x: -halfWidth * (formal ? 0.94 : 0.88), y: sport ? 0.48 : comfort ? 0.55 : 0.51, z: halfLength - 6e-3 }
