    ...structure,
    driverView,
    windshieldLowerBoundary: [0, boundaryY, boundaryZ],
    driverEye: config.driverEyePosition,
    steeringWheelCenter: config.steeringWheelPosition,
    steeringColumnAnchor: config.steeringColumnMountPosition ?? [
      config.steeringWheelPosition[0],
      config.cabin.dashboardTopY - 0.08,
      config.dashboard.position[2] + 0.04
    ],
    instrumentCenter: config.instrumentClusterTransform.position,
    instrumentPlane,
    instrumentRecessDepth: (structure.recessLip - instrumentPlane) * (config.instrumentClusterTransform.scale ?? 1),
    dashboardUpperFront: [0, cowlY, cowlZ],
    dashboardUpperRear: [0, upperY, rearZ],
    windshieldBase: [0, config.cabin.windshieldBottomY, config.cabin.windshieldBottomZ],
    windshieldTop: [0, config.cabin.windshieldTopY, config.cabin.windshieldTopZ],
    centerStackAnchor: [stackX, upperY - (driverView ? 0.02 : structure.thickness), rearZ],
    centerConsoleFront: [stackX, consoleHeight, structure.consoleFrontZ],
    centerConsoleHeight: consoleHeight,
    passengerDashAnchor: [(passengerLeft + passengerRight) * 0.5, upperY, rearZ],
    passengerDashDepth: rearZ - cowlZ,
    passengerLeft,
    passengerRight,
    gloveboxAnchor: [(passengerLeft + passengerRight) * 0.5, floorHeight + 0.28, rearZ - 0.05],
