      this.add(makeBox2("Premium EV rising centre console", [0.31, 0.18, 0.83], [0.1, 0.4, 0.19], interior));
      this.gearLever.name = "Premium EV compact selector";
      this.gearLever.position.set(-0.12, 0.76, -0.45);
