  root.add(rounded(side + " door sail mirror base", [0.042, 0.092, 0.115], start, black));
  const amber = path(side + " mirror amber repeater", [[-0.085, -0.028, -0.048], [0, -0.033, -0.067], [0.085, -0.024, -0.048]], 4e-3, black);
  amber.userData.lightingKey = side;
  g.add(amber);
  root.add(g);
  const surface = new Mesh(new PlaneGeometry(...c.size), new MeshStandardMaterial({ color: 11188936, metalness: 0.95, roughness: 0.03 }));
  surface.name = side + " mirror surface";
  surface.position.set(...c.position);
  surface.rotation.set(...c.rotation);
  surface.userData.mirrorSide = side;
  surface.renderOrder = 3;
  mirrorRoot.add(surface);
  root.traverse((o) => {
    if (o.name.startsWith(side + " mirror") || o.name === side + " door sail mirror base") o.userData.vehicleBodyPart = "mirror-housing";
  });
  g.traverse((o) => {
    o.userData.vehicleBodyPart = "mirror-housing";
  });
