function buildMercedesE300LSideMirror(root, mirrorRoot, side, c, paintColor) {
  const sign2 = side === "left" ? -1 : 1, group = new Group();
  group.name = side + " mirror assembly";
  group.position.set(...c.position);
  group.rotation.set(...c.rotation);
  const paint = new MeshPhysicalMaterial({
    color: paintColor,
    metalness: 0.62,
    roughness: 0.26,
    clearcoat: 0.9,
    side: DoubleSide
  });
  const black = new MeshStandardMaterial({ color: 856342, roughness: 0.58, side: DoubleSide });
  const outline2 = [];
  for (let i = 0; i < 40; i++) {
    const a = i / 40 * Math.PI * 2;
    outline2.push([
      Math.sign(Math.cos(a)) * Math.abs(Math.cos(a)) ** 0.38 * (c.size[0] / 2 + 0.016),
      Math.sign(Math.sin(a)) * Math.abs(Math.sin(a)) ** 0.48 * (c.size[1] / 2 + 0.015),
      0
    ]);
  }
  group.add(grid2(side + " curved mirror housing", 40, 8, (u, v) => {
    const a = u * Math.PI * 2, t = Math.cos(v * Math.PI / 2), z = -c.housingDepth * Math.sin(v * Math.PI / 2);
    return [
      Math.sign(Math.cos(a)) * Math.abs(Math.cos(a)) ** 0.38 * (c.size[0] / 2 + 0.016) * t,
      Math.sign(Math.sin(a)) * Math.abs(Math.sin(a)) ** 0.48 * (c.size[1] / 2 + 0.015) * t,
      z
    ];
  }, paint));
  group.add(path2(side + " mirror edge gasket", outline2, 6e-3, black, true));
  const start = c.mountPosition;
  root.add(beam2(
    side + " mirror stalk",
    start,
    [c.position[0] - sign2 * 0.072, c.position[1] - 0.022, c.position[2] - 0.028],
    0.02,
    black
  ));
  root.add(rounded2(side + " door sail mirror base", [0.044, 0.094, 0.118], start, black));
  const repeater = path2(
    side + " mirror amber repeater",
    [[-0.09, -0.03, -0.044], [0, -0.034, -0.06], [0.09, -0.026, -0.044]],
    35e-4,
    black
  );
  repeater.userData.lightingKey = side;
  group.add(repeater);
  root.add(group);
  const surface = new Mesh(
    new PlaneGeometry(...c.size),
    new MeshStandardMaterial({ color: 11122884, metalness: 0.95, roughness: 0.03 })
  );
  surface.name = side + " mirror surface";
  surface.position.set(...c.position);
  surface.rotation.set(...c.rotation);
  surface.userData.mirrorSide = side;
  surface.renderOrder = 3;
  mirrorRoot.add(surface);
  group.traverse((object) => {
    object.userData.vehicleBodyPart = "mirror-housing";
  });
  for (const name of [side + " mirror stalk", side + " door sail mirror base"]) {
    const part = root.getObjectByName(name);
    if (part) part.userData.vehicleBodyPart = "mirror-housing";
  }
  surface.userData.mountDirection = new Vector3(...c.position).sub(new Vector3(...start)).normalize();
  return surface;
}

