    const tyreGeometry = new LatheGeometry(profile2, 64);
    tyreGeometry.rotateZ(Math.PI / 2);
    const barrelGeometry = new CylinderGeometry(0.2545, 0.2545, width * 0.9, 48, 1, true);
    barrelGeometry.rotateZ(Math.PI / 2);
    const discGeometry = new CylinderGeometry(0.19, 0.19, 0.013, 48);
    discGeometry.rotateZ(Math.PI / 2);
    const lipGeometry = new TorusGeometry(0.2525, 85e-4, 8, 64);
    lipGeometry.rotateY(Math.PI / 2);
